"""Pictogramas dos exercícios avulsos (aba Exercícios), no estilo dos ícones do Samsung Health:
figuras de traço grosso e cabeça cheia, numa cor só (a cor de destaque). Desenho próprio, viewBox 24.
Injeta `const AIC={...}` em app.html entre /*AIC-START*/ e /*AIC-END*/ e grava tools/exicons.html (prancha).
Uso: python3 tools/exicons.py"""
import os, re

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
W = 2.9      # membros
T = 4.1      # tronco


def L(*pts, w=W):
    d = 'M' + ' L'.join(f'{x:g} {y:g}' for x, y in pts)
    return f'<path d="{d}" stroke-width="{w}"/>'


def H(x, y, r=2.55):
    return f'<circle cx="{x:g}" cy="{y:g}" r="{r:g}" fill="currentColor" stroke="none"/>'


def C(x, y, r, w=1.8, fill=False):
    return f'<circle cx="{x:g}" cy="{y:g}" r="{r:g}" stroke-width="{w}"{" fill=\"currentColor\" stroke=\"none\"" if fill else ""}/>'


def P(d, w=1.8, fill=False):
    return f'<path d="{d}" stroke-width="{w}"{" fill=\"currentColor\" stroke=\"none\"" if fill else ""}/>'


def G(inner, tr):
    return f'<g transform="{tr}">{inner}</g>'


WAVE = lambda y, w=1.9: P(f'M2 {y}c1.7 1.3 3.3 1.3 5 0s3.3-1.3 5 0 3.3 1.3 5 0 3.3-1.3 5 0', w)

