MAP = {'caminhada': 'walk', 'corrida': 'run', 'esteira': 'treadmill', 'corridaPista': 'track', 'trilha': 'hike', 'bicicleta': 'bike', 'bikeIndoor': 'bikeIndoor', 'mtb': 'mtb',
       'natacao': 'swim', 'marAberto': 'openwater', 'hidro': 'hydro', 'remo': 'row', 'caiaque': 'kayak', 'surfe': 'surf', 'sup': 'sup',
       'eliptico': 'elliptical', 'step': 'step', 'escada': 'stairs', 'remoMaq': 'rowmachine', 'circuito': 'circuit', 'hiit': 'hiit', 'crossfit': 'crossfit', 'abdominais': 'abs', 'pularCorda': 'rope', 'aerobico': 'aerobic', 'danca': 'dance', 'ioga': 'yoga', 'pilates': 'pilates', 'alongamento': 'stretch',
       'lutas': 'martial', 'boxe': 'boxing', 'futebol': 'soccer', 'futsal': 'soccer', 'basquete': 'basket', 'volei': 'volley', 'voleiPraia': 'volley', 'tenis': 'tennis', 'beachTennis': 'tennis', 'padel': 'tennis', 'tenisMesa': 'tabletennis', 'badminton': 'badminton', 'handebol': 'handball', 'squash': 'tennis', 'golfe': 'golf',
       'escalada': 'climb', 'patinacao': 'skate', 'skate': 'skateboard', 'subirEscadas': 'stairs', 'cavalgada': 'horse', 'esqui': 'ski', 'snowboard': 'snowboard', 'patinacaoGelo': 'iceskate', 'outro': 'other'}


def svg(k):
    return f'<svg class="i px" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{I[k]}</svg>'


def main():
    js = '/*AIC-START*/const AIC={' + ','.join(f'{k}:`{svg(k)}`' for k in I) + '};const AIC_OF=' + str(MAP).replace("'", '"') + ';/*AIC-END*/'
    p = os.path.join(ROOT, 'app.html'); s = open(p, encoding='utf-8').read()
    s, n = re.subn(r'/\*AIC-START\*/.*?/\*AIC-END\*/', lambda _: js, s, flags=re.S)
    assert n == 1, 'marcadores /*AIC-START*/ /*AIC-END*/ não encontrados'
    open(p, 'w', encoding='utf-8').write(s)
    cells = ''.join(f'<figure>{svg(v)}<figcaption>{k}</figcaption></figure>' for k, v in MAP.items())
    open(os.path.join(ROOT, 'tools', 'exicons.html'), 'w', encoding='utf-8').write(
        '<!doctype html><meta charset="utf-8"><style>body{font:11px sans-serif;margin:12px;background:#fff;display:grid;grid-template-columns:repeat(9,1fr);gap:8px}figure{margin:0;text-align:center}svg{width:56px;height:56px;color:#2EAD6B}</style>' + cells)
    print(len(I), 'pictogramas,', len(MAP), 'exercícios')


if __name__ == '__main__':
    main()
